"""Evaluation helpers (R9, R10).

Every function takes the anomaly *scores* first and the labels second, so labels
are only ever consumed after scores have been produced (unsupervised protocol).
"""

from __future__ import annotations

from typing import Dict, List, Sequence

import numpy as np
from sklearn.metrics import average_precision_score, precision_recall_curve, roc_auc_score


def auc_roc(scores: np.ndarray, labels: np.ndarray) -> float:
    """R9: AUC of the ROC curve.  Higher score == more anomalous."""
    return float(roc_auc_score(labels, scores))


def auc_pr(scores: np.ndarray, labels: np.ndarray) -> float:
    """R9: area under the precision-recall curve.

    Primary variant is scikit-learn's ``average_precision_score`` (the step-wise
    AP used by ADBench); the trapezoidal PR-AUC is reported as a secondary check.
    """
    return float(average_precision_score(labels, scores))


def auc_pr_trapz(scores: np.ndarray, labels: np.ndarray) -> float:
    precision, recall, _ = precision_recall_curve(labels, scores)
    return float(np.trapezoid(precision, recall))


def summarize(values: Sequence[float]) -> Dict[str, float]:
    """Mean / std / min / max over the repeats (R8)."""
    v = np.asarray(list(values), dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=0)),
        "std_sample": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
    }


def evaluate_all(scores: np.ndarray, labels: np.ndarray) -> Dict[str, float]:
    return {
        "auc_roc": auc_roc(scores, labels),
        "auc_pr": auc_pr(scores, labels),
        "auc_pr_trapz": auc_pr_trapz(scores, labels),
    }
